IF DB_ID(N'SmartAttend') IS NULL EXEC(N'CREATE DATABASE SmartAttend');
GO
USE SmartAttend;
GO
IF OBJECT_ID(N'dbo.Departments',N'U') IS NULL CREATE TABLE Departments (DepartmentId int IDENTITY PRIMARY KEY, Name nvarchar(100) NOT NULL UNIQUE);
IF OBJECT_ID(N'dbo.Classes',N'U') IS NULL CREATE TABLE Classes (ClassId int IDENTITY PRIMARY KEY, DepartmentId int NOT NULL REFERENCES Departments, Name nvarchar(80) NOT NULL, Semester tinyint NOT NULL CHECK (Semester BETWEEN 1 AND 12), AcademicYear nvarchar(20) NOT NULL, UNIQUE(DepartmentId,Name,AcademicYear));
IF OBJECT_ID(N'dbo.Students',N'U') IS NULL CREATE TABLE Students (StudentId int IDENTITY PRIMARY KEY, EnrollmentNumber nvarchar(30) NOT NULL UNIQUE, FullName nvarchar(120) NOT NULL, Email nvarchar(256) NULL, PhoneNumber nvarchar(30) NULL, ClassId int NULL REFERENCES Classes, EnrollmentDate date NOT NULL DEFAULT CAST(GETDATE() AS date), IsActive bit NOT NULL DEFAULT 1);
IF OBJECT_ID(N'dbo.Teachers',N'U') IS NULL CREATE TABLE Teachers (TeacherId int IDENTITY PRIMARY KEY, FullName nvarchar(120) NOT NULL, Email nvarchar(256) NULL UNIQUE, IsActive bit NOT NULL DEFAULT 1);
IF OBJECT_ID(N'dbo.Subjects',N'U') IS NULL CREATE TABLE Subjects (SubjectId int IDENTITY PRIMARY KEY, ClassId int NOT NULL REFERENCES Classes, Code nvarchar(30) NOT NULL, Name nvarchar(120) NOT NULL, UNIQUE(ClassId,Code));
IF OBJECT_ID(N'dbo.TeacherAssignments',N'U') IS NULL CREATE TABLE TeacherAssignments (TeacherId int NOT NULL REFERENCES Teachers, SubjectId int NOT NULL REFERENCES Subjects, PRIMARY KEY(TeacherId,SubjectId));
IF OBJECT_ID(N'dbo.AttendanceSessions',N'U') IS NULL CREATE TABLE AttendanceSessions (SessionId int IDENTITY PRIMARY KEY, SubjectId int NOT NULL REFERENCES Subjects, TeacherId int NOT NULL REFERENCES Teachers, SessionDate date NOT NULL, Period nvarchar(30) NULL, CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), UNIQUE(SubjectId,SessionDate,Period));
IF OBJECT_ID(N'dbo.AttendanceRecords',N'U') IS NULL CREATE TABLE AttendanceRecords (RecordId int IDENTITY PRIMARY KEY, SessionId int NOT NULL REFERENCES AttendanceSessions ON DELETE CASCADE, StudentId int NOT NULL REFERENCES Students, Status nvarchar(10) NOT NULL CHECK(Status IN ('Present','Absent','Late','Excused')), Remarks nvarchar(300) NULL, UNIQUE(SessionId,StudentId));
IF OBJECT_ID(N'dbo.AttendanceAuditLogs',N'U') IS NULL CREATE TABLE AttendanceAuditLogs (AuditId bigint IDENTITY PRIMARY KEY, RecordId int NULL, ChangedBy nvarchar(256) NOT NULL, ChangeDescription nvarchar(500) NOT NULL, CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
IF OBJECT_ID(N'dbo.ApplicationSettings',N'U') IS NULL CREATE TABLE ApplicationSettings ([Key] nvarchar(100) PRIMARY KEY, [Value] nvarchar(1000) NOT NULL);
IF OBJECT_ID(N'dbo.AppUsers',N'U') IS NULL CREATE TABLE AppUsers (AppUserId int IDENTITY PRIMARY KEY, Email nvarchar(256) NOT NULL, NormalizedEmail nvarchar(256) NOT NULL UNIQUE, PasswordHash nvarchar(500) NOT NULL, Role nvarchar(20) NOT NULL CHECK(Role IN('Administrator','Teacher','Student')), StudentId int NULL UNIQUE REFERENCES Students(StudentId), TeacherId int NULL UNIQUE REFERENCES Teachers(TeacherId), IsActive bit NOT NULL DEFAULT 1, CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), CONSTRAINT CK_AppUsers_Link CHECK((Role='Administrator' AND StudentId IS NULL AND TeacherId IS NULL) OR (Role='Teacher' AND TeacherId IS NOT NULL AND StudentId IS NULL) OR (Role='Student' AND StudentId IS NOT NULL AND TeacherId IS NULL)));
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name=N'IX_AttendanceSessions_Date' AND object_id=OBJECT_ID(N'dbo.AttendanceSessions')) CREATE INDEX IX_AttendanceSessions_Date ON AttendanceSessions(SessionDate);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name=N'IX_AttendanceRecords_Student' AND object_id=OBJECT_ID(N'dbo.AttendanceRecords')) CREATE INDEX IX_AttendanceRecords_Student ON AttendanceRecords(StudentId,SessionId);
